#include "dma.h"
int dma_owner_init(struct dma_owner*o,uint32_t id,void*c,dma_backend_map_fn m,dma_backend_unmap_fn u){if(!o||!id||!m||!u)return -1;o->id=id;o->context=c;o->map=m;o->unmap=u;o->alive=1;o->next_generation=1;for(uint32_t i=0;i<DMA_MAX_MAPPINGS;i++)o->mappings[i].active=0;return 0;}
int dma_map(struct dma_owner*o,uint64_t p,uint64_t n,uint8_t d,struct dma_mapping*out){if(!o||!out||!o->alive||!o->next_generation||!n||p>~0ULL-n||(d!=DMA_TO_DEVICE&&d!=DMA_FROM_DEVICE&&d!=DMA_BIDIRECTIONAL))return -1;uint32_t i;for(i=0;i<DMA_MAX_MAPPINGS&&o->mappings[i].active;i++);if(i==DMA_MAX_MAPPINGS)return -2;uint64_t bus;if(o->map(o->context,p,n,d,&bus)!=0)return -3;if(bus>~0ULL-n){(void)o->unmap(o->context,bus,n,d);return -3;}struct dma_mapping*m=&o->mappings[i];m->bus_address=bus;m->physical_address=p;m->length=n;m->direction=d;m->owner_id=o->id;m->generation=o->next_generation++;m->active=1;*out=*m;return 0;}
int dma_unmap(struct dma_owner*o,struct dma_mapping*t){if(!o||!t||!o->alive||!t->active||t->owner_id!=o->id)return -1;for(uint32_t i=0;i<DMA_MAX_MAPPINGS;i++){struct dma_mapping*m=&o->mappings[i];if(m->active&&m->generation==t->generation&&m->bus_address==t->bus_address&&m->length==t->length&&m->direction==t->direction){if(o->unmap(o->context,m->bus_address,m->length,m->direction)!=0)return -2;m->active=0;t->active=0;return 0;}}return -1;}
int dma_owner_destroy(struct dma_owner*o){if(!o||!o->alive)return -1;for(uint32_t i=0;i<DMA_MAX_MAPPINGS;i++)if(o->mappings[i].active)return -2;o->alive=0;return 0;}
